  // Attendance mile to student.attendance override karo (warna jo aya wahi — mostly '—').
  const stEff = attnPct != null ? { ...student, attendance: `${attnPct}%` } : student;

  const tConfig = RC_TEMPLATES.find(x => x.id === template) || RC_TEMPLATES[0];

